-- SPDX-License-Identifier: GPL-3.0-or-later
-- TrigIT 0.1.0 for grandMA3. Generated by ma3-plugin/build.lua from src/ and
-- adapter/: edit those, not this file. https://github.com/jrikner/TrigIT

local modules, loaded = {}, {}
local function require(name)
    if loaded[name] == nil then loaded[name] = modules[name]() end
    return loaded[name]
end

modules["json"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- A small JSON decoder: enough for .trigit Set files, in plain Lua 5.4.
-- null decodes as nil. Errors are raised with the byte position.

local json = {}

local escapes = { ['"'] = '"', ["\\"] = "\\", ["/"] = "/", b = "\b", f = "\f", n = "\n", r = "\r", t = "\t" }

function json.decode(text)
    local pos = 1
    local function fail(what) error(("%s at byte %d"):format(what, pos), 0) end
    local function skip() pos = text:find("[^ \t\r\n]", pos) or #text + 1 end
    local function peek() return text:sub(pos, pos) end

    local function str()
        pos = pos + 1
        local parts = {}
        while true do
            local at = text:find('["\\]', pos)
            if not at then fail("unterminated string") end
            parts[#parts + 1] = text:sub(pos, at - 1)
            if text:sub(at, at) == '"' then
                pos = at + 1
                return table.concat(parts)
            end
            local c = text:sub(at + 1, at + 1)
            if c == "u" then
                local hex = text:match("^%x%x%x%x", at + 2) or fail("bad \\u escape")
                local code = tonumber(hex, 16)
                pos = at + 6
                local low = code >= 0xD800 and code <= 0xDBFF and text:match("^\\u(%x%x%x%x)", pos)
                if low then
                    code = 0x10000 + (code - 0xD800) * 0x400 + (tonumber(low, 16) - 0xDC00)
                    pos = pos + 6
                end
                parts[#parts + 1] = utf8.char(code)
            else
                parts[#parts + 1] = escapes[c] or fail("bad escape")
                pos = at + 2
            end
        end
    end

    local value
    local function list(close, item)
        pos = pos + 1
        skip()
        if peek() == close then pos = pos + 1 return end
        while true do
            item()
            skip()
            local c = peek()
            pos = pos + 1
            if c == close then return end
            if c ~= "," then fail("expected ',' or '" .. close .. "'") end
        end
    end

    function value()
        skip()
        local c = peek()
        if c == "{" then
            local object = {}
            list("}", function()
                skip()
                if peek() ~= '"' then fail("expected a key") end
                local key = str()
                skip()
                if peek() ~= ":" then fail("expected ':'") end
                pos = pos + 1
                object[key] = value()
            end)
            return object
        elseif c == "[" then
            local array, n = {}, 0
            list("]", function() n = n + 1; array[n] = value() end)
            return array
        elseif c == '"' then
            return str()
        end
        for word, result in pairs({ ["true"] = true, ["false"] = false, null = json }) do
            if text:sub(pos, pos + #word - 1) == word then
                pos = pos + #word
                if result == json then return nil end
                return result
            end
        end
        local number = text:match("^-?%d+%.?%d*[eE]?[-+]?%d*", pos)
        if not number or not tonumber(number) then fail("unexpected character") end
        pos = pos + #number
        return tonumber(number)
    end

    local result = value()
    skip()
    if pos <= #text then fail("trailing characters") end
    return result
end

return json

end

modules["commands"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- Every grandMA3 command the plugin writes is formatted here and nowhere else.
-- Checked on grandMA3 onPC 2.5.1 against the bytes that arrive (see README.md);
-- not yet on a console (spike #43).

local commands = {}

-- The adapter replaces this with the In & Out OSC line the Destination maps to.
commands.OSC_LINE = "$line"

-- How long a MIDI note is held, as the Mac app does (MIDIOutput.noteLength).
commands.NOTE_LENGTH = 0.1

local function number(value)
    return math.type(value) == "integer" and tostring(value) or ("%.9g"):format(value)
end

-- SendOSC <line> "/address,<type tags>,<arg>,<arg>". With no arguments it is
-- "/address," (MA3 refuses a bare address), which sends the same bytes as the
-- Mac app. Returns nil and a reason for strings SendOSC can't carry: a comma
-- splits the argument and a quote ends the command's string.
function commands.osc(message)
    local tags, args = {}, {}
    for _, argument in ipairs(message.arguments) do
        if argument.int then
            tags[#tags + 1], args[#args + 1] = "i", number(argument.int)
        elseif argument.float then
            tags[#tags + 1], args[#args + 1] = "f", number(argument.float)
        else
            if argument.string:find('[,"]') then
                return nil, ('the OSC string %q contains a comma or quote, which SendOSC can\'t send'):format(argument.string)
            end
            tags[#tags + 1], args[#args + 1] = "s", argument.string
        end
    end
    local body = message.address .. "," .. table.concat(tags)
    if #args > 0 then body = body .. "," .. table.concat(args, ",") end
    return ('SendOSC %s "%s"'):format(commands.OSC_LINE, body)
end

-- SendMIDI "Note" <channel 1-16>/<note> <velocity>, then velocity 0 (Note Off)
-- after NOTE_LENGTH. MA3 sends it on the console's MIDI output.
function commands.midiNote(note)
    local function send(velocity) return ('SendMIDI "Note" %d/%d %d'):format(note.channel + 1, note.note, velocity) end
    return send(note.velocity), { after = commands.NOTE_LENGTH, command = send(0) }
end

return commands

end

modules["trigit_plan"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- Turns a TrigIT Set (extended CSV or a .trigit file) into a plan for a
-- grandMA3 Timecode Show. Pure Lua 5.4: no MA API calls. The rules follow
-- TrigIT's GLOSSARY.md and the Mac app (SetEditing.swift, ShowEngine.swift).

local json = require("json")
local commands = require("commands")

local plan = {}

-- Frames per timecode second for each rate TrigIT knows (FrameRate.swift).
local FRAMES = { ["24"] = 24, ["25"] = 25, ["29.97 DF"] = 30, ["30"] = 30 }
local TRANSPORT = { osc = "osc", midiNote = "midi", msc = "midi", dmxPulse = "dmx" }
local TRANSPORT_NAME = { osc = "OSC", midi = "MIDI", dmx = "DMX" }
-- MA3 has no checked way to send these yet: MSC from a command, or a DMX
-- pulse to a channel without taking it from the console's own output.
local UNSUPPORTED = { msc = "MIDI Show Control", dmxPulse = "DMX pulse" }

local function trim(text) return (text:gsub("^%s+", ""):gsub("%s+$", "")) end

-- "hh:mm:ss:ff" (";" or "." also allowed before any field, as in the app),
-- normalised to two digits a field so timecodes compare as strings. Frames up
-- to 29, as the app accepts when it knows no frame rate.
local function parseTimecode(text)
    local fields = {}
    for field in (trim(text) .. ":"):gmatch("([^:;.]*)[:;.]") do fields[#fields + 1] = field end
    if #fields ~= 4 then return nil end
    for i, field in ipairs(fields) do
        if not field:match("^%d%d?$") then return nil end
        fields[i] = tonumber(field)
    end
    local h, m, s, f = table.unpack(fields)
    if h > 23 or m > 59 or s > 59 or f > 29 then return nil end
    return ("%02d:%02d:%02d:%02d"):format(h, m, s, f)
end

-- The frame after `timecode`: where the Playhead has played on past a Song's
-- end, which is when the app sends its Stop Actions.
local function nextFrame(timecode, rate)
    local h, m, s, f = timecode:match("(%d+):(%d+):(%d+):(%d+)")
    h, m, s, f = tonumber(h), tonumber(m), tonumber(s), tonumber(f) + 1
    if f >= FRAMES[rate] then f, s = 0, s + 1 end
    if s > 59 then s, m = 0, m + 1 end
    if m > 59 then m, h = 0, (h + 1) % 24 end
    -- Drop-frame skips frames 0 and 1 at each minute except every tenth.
    if rate == "29.97 DF" and s == 0 and f < 2 and m % 10 ~= 0 then f = 2 end
    return ("%02d:%02d:%02d:%02d"):format(h, m, s, f)
end

-- The MA command for one Action to its Destination ({ name, uses }), and its
-- release (a later Note Off) if any; or nil and why it can't be sent.
local function commandFor(action, destination)
    local transport = TRANSPORT[action.type]
    if not destination then
        return nil, "an Action sends to a Destination that isn't in the Set; left out"
    elseif not destination.uses[transport] then
        return nil, ('Destination "%s" has %s switched off; Action left out'):format(destination.name, TRANSPORT_NAME[transport])
    elseif UNSUPPORTED[action.type] then
        return nil, UNSUPPORTED[action.type] .. " Actions aren't supported by the MA3 plugin yet; left out"
    end
    return commands[action.type](action[action.type])
end

-- A Destination as the plan uses it, from one in a .trigit file.
local function destinationFrom(d)
    -- Older files: OSC on, MIDI and DMX on if their output is set (Coding.swift).
    local uses = { osc = d.usesOSC ~= false, midi = d.usesMIDI, dmx = d.usesDMX }
    if uses.midi == nil then uses.midi = d.midiOutput ~= nil end
    if uses.dmx == nil then uses.dmx = d.dmxOutput ~= nil end
    return { name = d.name or "", uses = uses, host = d.host or "", port = d.port or 0, midiPort = d.midiOutput and d.midiOutput.name }
end

-- Builds the plan from Songs, each { name, where, hasSpan, start, ["end"],
-- startNote, stopNote, startActions, stopActions }, whose Actions carry their
-- resolved Destination (or nil if missing). Same rules for both inputs.
local function build(songs, destinations, frameRate, warnings)
    local events, accepted = {}, {}
    local function warn(where, reason) warnings[#warnings + 1] = where .. ": " .. reason end

    for _, song in ipairs(songs) do
        local conflict
        if song.hasSpan and song.start <= song["end"] then
            for _, other in ipairs(accepted) do
                if song.start <= other["end"] and other.start <= song["end"] then conflict = other break end
            end
        end
        if not song.hasSpan then
            local notes = song.startNote and song.stopNote and "a Start Note and a Stop Note"
                or song.startNote and "a Start Note" or song.stopNote and "a Stop Note" or "no trigger"
            warn(song.where, ("skipped: it has %s and no timecode span, so it can't become timecode events"):format(notes))
        elseif song.start > song["end"] then
            warn(song.where, "skipped: end is before start")
        elseif conflict then
            warn(song.where, ('overlaps "%s"'):format(conflict.name))
        else
            accepted[#accepted + 1] = song
            for _, time in ipairs({ song.start, song["end"] }) do
                local frames = tonumber(time:sub(-2))
                if frames >= FRAMES[frameRate] then
                    warn(song.where, ("%s has frame %d, past the last frame at %s fps"):format(time, frames, frameRate))
                end
            end
            for _, phase in ipairs({ "start", "stop" }) do
                local time = phase == "start" and song.start or nextFrame(song["end"], frameRate)
                for _, action in ipairs(song[phase .. "Actions"]) do
                    local destination, transport = action.destination, TRANSPORT[action.type]
                    local command, release = commandFor(action, destination)
                    if command then
                        local key = transport == "osc" and "osc_line_for" or transport .. "_for"
                        events[#events + 1] = {
                            time = time, song = song.name, phase = phase,
                            destination = { [key] = destination.name },
                            command = command, release = release,
                        }
                    else
                        warn(action.where or song.where, release)
                    end
                end
            end
        end
    end

    -- Timecode order; Actions keep their list order within one time.
    for i, event in ipairs(events) do event.order = i end
    table.sort(events, function(a, b) return a.time < b.time or a.time == b.time and a.order < b.order end)
    for _, event in ipairs(events) do event.order = nil end

    local list = {}
    for _, destination in ipairs(destinations) do
        local kinds = {}
        for _, transport in ipairs({ "osc", "midi", "dmx" }) do
            if destination.uses[transport] then kinds[#kinds + 1] = transport end
        end
        list[#list + 1] = {
            name = destination.name, kind = table.concat(kinds, "+"),
            host = destination.host, port = destination.port, midiPort = destination.midiPort,
        }
    end
    return { frameRate = frameRate, destinations = list, events = events, warnings = warnings }
end

local function checkRate(options)
    local rate = options and options.frameRate or "30"
    if not FRAMES[rate] then error(('frame rate "%s" is not 24, 25, 29.97 DF or 30'):format(rate), 3) end
    return rate
end

-- MARK: .trigit

-- The "set" of a .trigit file (SetFile.swift), as the Show Engine takes it;
-- or nil and the reason the file can't be read, worded as the Mac app words it.
function plan.readSet(text)
    local ok, file = pcall(json.decode, text)
    if not ok then return nil, "The file is not a TrigIT Set (it isn't JSON)." end
    if type(file) ~= "table" or file.format ~= "TrigIT Set" or math.type(file.version) ~= "integer" then
        return nil, "The file is JSON, but not a TrigIT Set."
    end
    if file.version > 1 then
        return nil, ("The Set was saved by a newer TrigIT (file version %d); update TrigIT to open it."):format(file.version)
    end
    if type(file.set) ~= "table" then return nil, 'The Set file is damaged: it has no "set".' end
    return file.set
end

-- The command for one Action the Show Engine sends, to its Destination as
-- the .trigit file has it: as commandFor, OSC with commands.OSC_LINE still in.
function plan.liveCommand(action, destination)
    return commandFor(action, destinationFrom(destination))
end

-- Reads a Set file written by SetFile.swift. Returns the plan, or nil and the
-- reason the file can't be read (worded as the Mac app words it).
function plan.fromTrigit(text, options)
    local frameRate = checkRate(options)
    local set, reason = plan.readSet(text)
    if not set then return nil, reason end

    local ok, built = pcall(function()
        local byID, destinations = {}, {}
        for _, d in ipairs(set.destinations or {}) do
            local destination = destinationFrom(d)
            byID[d.id] = destination
            destinations[#destinations + 1] = destination
        end
        local songs = {}
        for _, s in ipairs(set.songs or {}) do
            local song = {
                name = s.name or "", where = ('Song "%s"'):format(s.name or ""), hasSpan = s.start ~= nil,
                startNote = s.startNote, stopNote = s.stopNote, startActions = {}, stopActions = {},
            }
            if song.hasSpan then
                song.start = parseTimecode(s.start) or error(('"%s" is not a timecode (hh:mm:ss:ff)'):format(s.start), 0)
                song["end"] = parseTimecode(s["end"] or "") or error(('"%s" is not a timecode (hh:mm:ss:ff)'):format(s["end"]), 0)
            end
            for _, phase in ipairs({ "startActions", "stopActions" }) do
                for _, a in ipairs(s[phase] or {}) do
                    local action = { type = a.type, destination = byID[a.destination] }
                    if not TRANSPORT[a.type] then error(('"%s" is not an Action type'):format(tostring(a.type)), 0) end
                    action[a.type] = a[a.type]
                    song[phase][#song[phase] + 1] = action
                end
            end
            songs[#songs + 1] = song
        end
        return build(songs, destinations, frameRate, {})
    end)
    if not ok then return nil, "The Set file is damaged: " .. tostring(built) .. "." end
    return built
end

-- MARK: CSV

-- The separator used most on the first non-empty line, outside quotes; a
-- comma on a tie.
local function detectSeparator(lines)
    for _, line in ipairs(lines) do
        if line:find("%S") then
            local counts, inQuotes = { [","] = 0, [";"] = 0, ["\t"] = 0 }, false
            for c in line:gmatch(".") do
                if c == '"' then inQuotes = not inQuotes end
                if not inQuotes and counts[c] then counts[c] = counts[c] + 1 end
            end
            local best = ","
            for _, separator in ipairs({ ";", "\t" }) do
                if counts[separator] > counts[best] then best = separator end
            end
            return best
        end
    end
    return ","
end

-- Trimmed fields; quoted fields may hold the separator, and "" is a quote.
local function splitCSV(line, separator)
    local fields, field, inQuotes, i = {}, {}, false, 1
    while i <= #line do
        local c = line:sub(i, i)
        if inQuotes then
            if c == '"' and line:sub(i + 1, i + 1) == '"' then
                field[#field + 1] = '"'
                i = i + 1
            elseif c == '"' then
                inQuotes = false
            else
                field[#field + 1] = c
            end
        elseif c == '"' then
            inQuotes = true
        elseif c == separator then
            fields[#fields + 1] = trim(table.concat(field))
            field = {}
        else
            field[#field + 1] = c
        end
        i = i + 1
    end
    fields[#fields + 1] = trim(table.concat(field))
    return fields
end

-- OSC arguments typed as text, as the app's editor reads them
-- (OSCArgument.parseList): whole numbers are ints, numbers with ".", "e" or
-- "E" are floats, anything else a string; quotes keep spaces or a number as
-- text, with \ escaping the next character. Nil for an unterminated quote.
local function parseArguments(text)
    local arguments, i = {}, 1
    while true do
        i = text:find("%S", i)
        if not i then return arguments end
        if text:sub(i, i) == '"' then
            local value, closed = {}, false
            i = i + 1
            while i <= #text do
                local c = text:sub(i, i)
                if c == "\\" and i < #text then
                    i = i + 1
                    value[#value + 1] = text:sub(i, i)
                elseif c == '"' then
                    closed = true
                    break
                else
                    value[#value + 1] = c
                end
                i = i + 1
            end
            if not closed then return nil end
            arguments[#arguments + 1] = { string = table.concat(value) }
            i = i + 1
        else
            local token = text:match("^%S+", i)
            i = i + #token
            local int, float = token:match("^[-+]?%d+$") and tonumber(token), tonumber(token)
            if int and int >= -2 ^ 31 and int < 2 ^ 31 then
                arguments[#arguments + 1] = { int = math.tointeger(int) }
            elseif token:find("[.eE]") and float and math.abs(float) <= 3.4028234663852886e38 then
                arguments[#arguments + 1] = { float = float + 0.0 }
            else
                arguments[#arguments + 1] = { string = token }
            end
        end
    end
end

local function integerIn(text, low, high)
    local value = text:match("^%d+$") and tonumber(text)
    return value and value >= low and value <= high and value or nil
end

-- The Action in columns 4-8, or nil (and a reason, if there is one wrong).
local function parseAction(columns)
    local destination, kind, target, value, phase = columns[4] or "", (columns[5] or ""):lower(),
        columns[6] or "", columns[7] or "", (columns[8] or ""):lower()
    if destination .. kind .. target .. value .. phase == "" then return nil end
    if destination == "" then return nil, "the Action has no destination" end
    if phase ~= "" and phase ~= "start" and phase ~= "stop" then
        return nil, ('when "%s" is not start or stop'):format(columns[8])
    end
    local action = { destination = destination, phase = phase == "stop" and "stop" or "start" }
    if kind == "osc" then
        -- OSC addresses start with "/" and are printable ASCII without spaces, '#' or ','.
        if not target:match("^/[\33-\126]*$") or target:find("[#,]") then
            return nil, ('"%s" is not an OSC address'):format(target)
        end
        local arguments = parseArguments(value)
        if not arguments then return nil, ('arguments "%s" have an unterminated quote'):format(value) end
        action.type, action.osc = "osc", { address = target, arguments = arguments }
    elseif kind == "midi-note" then
        local channelText, noteText = target:match("^(%d+)/(%d+)$")
        local channel = channelText and integerIn(channelText, 1, 16) or not channelText and 1
        local note = integerIn(noteText or target, 0, 127)
        if not channel or not note then return nil, ('note "%s" is not a note (60, or channel/note as 10/36)'):format(target) end
        local velocity = value == "" and 127 or integerIn(value, 1, 127)
        if not velocity then return nil, ('velocity "%s" is not 1-127'):format(value) end
        action.type, action.midiNote = "midiNote", { channel = channel - 1, note = note, velocity = velocity }
    elseif kind == "dmx" then
        local universeText, channelText = target:match("^(%d+)%.(%d+)$")
        local universe = universeText and integerIn(universeText, 0, 63999)
        local channel = channelText and integerIn(channelText, 1, 512)
        if not universe or not channel then
            return nil, ('"%s" is not universe.channel (channel 1-512)'):format(target)
        end
        local level = value == "" and 255 or integerIn(value, 0, 255)
        if not level then return nil, ('value "%s" is not 0-255'):format(value) end
        action.type, action.dmxPulse = "dmxPulse", { universe = universe, channel = channel, value = level, duration = 0.5 }
    else
        return nil, ('kind "%s" is not osc, midi-note or dmx'):format(columns[5] or "")
    end
    return action
end

-- Reads the extended CSV described in README.md. Returns the plan; rows the
-- app's importer would refuse are reported in its warnings, with line numbers.
function plan.fromCSV(text, options)
    local frameRate = checkRate(options)
    local lines = {}
    for line in (text:gsub("\r\n", "\n"):gsub("\r", "\n") .. "\n"):gmatch("([^\n]*)\n") do lines[#lines + 1] = line end
    local separator = detectSeparator(lines)

    local warnings, songs, destinations, byName = {}, {}, {}, {}
    local isFirstRow, current = true, nil -- current: the Song above, or false if it was refused
    local function addAction(song, columns, where)
        local action, reason = parseAction(columns)
        if not action then
            if reason then warnings[#warnings + 1] = where .. ": " .. reason end
            return
        end
        local destination = byName[action.destination]
        if not destination then
            destination = { name = action.destination, uses = {} }
            byName[action.destination] = destination
            destinations[#destinations + 1] = destination
        end
        destination.uses[TRANSPORT[action.type]] = true
        action.destination, action.where = destination, where
        local list = song[action.phase .. "Actions"]
        list[#list + 1] = action
    end

    for lineNumber, line in ipairs(lines) do
        local columns = splitCSV(line, separator)
        if table.concat(columns) ~= "" then
            local firstRow = isFirstRow
            isFirstRow = false
            local where = "line " .. lineNumber
            local function problem(reason) warnings[#warnings + 1] = where .. ": " .. reason end
            local name, startText, endText = columns[1], columns[2] or "", columns[3] or ""

            if #columns < 3 then
                problem(("needs name, start and end; found %d column%s"):format(#columns, #columns == 1 and "" or "s"))
                current = false
            elseif name == "" and startText == "" and endText == "" then
                -- Another Action for the Song above.
                if current then
                    addAction(current, columns, where)
                else
                    problem(current == nil and "no Song above to add the Action to" or "the Song above was skipped")
                end
            else
                local start, finish = parseTimecode(startText), parseTimecode(endText)
                -- A first row whose times are both not timecodes is a header.
                if not (firstRow and not start and not finish) then
                    current = false
                    if name == "" then
                        problem("the name is empty")
                    elseif not start then
                        problem(('start "%s" is not a timecode (hh:mm:ss:ff)'):format(startText))
                    elseif not finish then
                        problem(('end "%s" is not a timecode (hh:mm:ss:ff)'):format(endText))
                    elseif finish < start then
                        problem("end is before start")
                    else
                        current = {
                            name = name, where = where, hasSpan = true, start = start, ["end"] = finish,
                            startActions = {}, stopActions = {},
                        }
                        songs[#songs + 1] = current
                        addAction(current, columns, where)
                    end
                end
            end
        end
    end
    local result = build(songs, destinations, frameRate, warnings)
    -- In line order: overlaps are found after the rows are read.
    local function line(i) return tonumber(warnings[i]:match("^line (%d+)")) end
    local order = {}
    for i in ipairs(warnings) do order[i] = i end
    table.sort(order, function(a, b) return line(a) < line(b) or line(a) == line(b) and a < b end)
    for i, index in ipairs(order) do order[i] = warnings[index] end
    result.warnings = order
    return result
end

return plan

end

modules["ma3"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- The pure part of the grandMA3 adapter: turns a plan into the cues the
-- adapter writes (one per moment, with their commands), so it can be tested
-- without a console. No MA API calls.

local ma3 = {}

local FRAMES = { ["24"] = 24, ["25"] = 25, ["29.97 DF"] = 30, ["30"] = 30 }

-- Seconds from 00:00:00:00 at `rate`, as the Timecode Show's timeline counts.
-- Drop-frame counts real time: frame numbers 0 and 1 are skipped at every
-- minute except each tenth, and frames run at 30000/1001 a second.
function ma3.seconds(timecode, rate)
    local h, m, s, f = timecode:match("^(%d+):(%d+):(%d+):(%d+)$")
    h, m, s, f = tonumber(h), tonumber(m), tonumber(s), tonumber(f)
    if rate == "29.97 DF" then
        local minutes = h * 60 + m
        local frames = (minutes * 60 + s) * 30 + f - 2 * (minutes - minutes // 10)
        return frames * 1001 / 30000
    end
    return h * 3600 + m * 60 + s + f / FRAMES[rate]
end

-- The cues for a plan, in time order: { seconds, name, command }. Events at
-- the same moment share a cue, their commands joined with "; " in plan order.
-- A release (a MIDI Note Off) becomes its own moment `after` seconds later.
-- `lines` maps a Destination's name to its In & Out OSC line number; events
-- for an OSC Destination without one are left out.
function ma3.cues(plan, lines)
    local cues, byMoment = {}, {}
    local function add(seconds, name, command)
        local key = ("%.4f"):format(seconds)
        local cue = byMoment[key]
        if not cue then
            cue = { seconds = seconds, name = name, commands = {} }
            byMoment[key] = cue
            cues[#cues + 1] = cue
        end
        cue.commands[#cue.commands + 1] = command
    end

    for _, event in ipairs(plan.events) do
        local command, line = event.command, event.destination.osc_line_for and lines[event.destination.osc_line_for]
        if line then command = command:gsub("%$line", tostring(line), 1) end
        if line or not event.destination.osc_line_for then
            local seconds = ma3.seconds(event.time, plan.frameRate)
            add(seconds, event.song .. " " .. event.phase, command)
            if event.release then add(seconds + event.release.after, event.song .. " note off", event.release.command) end
        end
    end

    table.sort(cues, function(a, b) return a.seconds < b.seconds end)
    for _, cue in ipairs(cues) do
        cue.command, cue.commands = table.concat(cue.commands, "; "), nil
    end
    return cues
end

return ma3

end

modules["timecode"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- Timecode as "hh:mm:ss:ff" strings, two digits a field, so they compare as
-- strings in time order. Frame counting as Sources/TrigITProtocols/TimecodeFields.swift.

local timecode = {}

-- Frames counted per timecode second, and per second of real time.
timecode.RATES = {
    ["24"] = { nominal = 24, real = 24 },
    ["25"] = { nominal = 25, real = 25 },
    ["29.97 DF"] = { nominal = 30, real = 30000 / 1001, dropFrame = true },
    ["30"] = { nominal = 30, real = 30 },
}

local function fields(text)
    local h, m, s, f = text:match("^(%d+):(%d+):(%d+):(%d+)$")
    return tonumber(h), tonumber(m), tonumber(s), tonumber(f)
end

-- Frames since 00:00:00:00. Drop-frame skips frame numbers 0 and 1 at the
-- start of every minute except each tenth.
function timecode.index(text, rate)
    local h, m, s, f = fields(text)
    local info = timecode.RATES[rate]
    local nominal = ((h * 60 + m) * 60 + s) * info.nominal + f
    if not info.dropFrame then return nominal end
    local minutes = h * 60 + m
    return nominal - 2 * (minutes - minutes // 10)
end

-- The timecode `index` frames after 00:00:00:00, wrapping at 24 hours.
function timecode.fromIndex(index, rate)
    local info = timecode.RATES[rate]
    local fps = info.nominal
    local day = info.dropFrame and 24 * 6 * 17982 or 24 * 3600 * fps
    local n = index % day
    if info.dropFrame then
        local blocks, remainder = n // 17982, n % 17982
        n = n + 18 * blocks + (remainder < 2 and 0 or 2 * ((remainder - 2) // 1798))
    end
    return ("%02d:%02d:%02d:%02d"):format(n // (3600 * fps), (n // (60 * fps)) % 60, (n // fps) % 60, n % fps)
end

-- The frame showing `seconds` after 00:00:00:00, as the Timecode Show's
-- timeline and a timecode slot count (ma3.seconds is the inverse).
function timecode.fromSeconds(seconds, rate)
    return timecode.fromIndex(math.floor(seconds * timecode.RATES[rate].real + 1e-6), rate)
end

return timecode

end

modules["engine"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- TrigIT's Show Engine in Lua: a line-for-line port of
-- Sources/TrigITEngine/ShowEngine.swift, with the same rules (GLOSSARY.md).
-- It follows timecode readings and decides when Songs fire and End. Pure: no
-- MA calls, no clock; time comes in through reading timestamps and tick().
--
-- The Set is the "set" of a decoded .trigit file: songs (id, name, start, end,
-- startNote, stopNote, startActions, stopActions; no start means no span),
-- destinations (with id) and stopTime. Timecodes are "hh:mm:ss:ff" strings.
--
-- Every call returns a list of events, in order, each a table with `kind`:
--   playheadMoved {timecode}            frameRateChanged {frameRate}
--   jumped {from, to}                   currentSongChanged {song} (nil: none)
--   fired {song, cause}                 cause: "entering" | "note" | "manual"
--   ended {song, cause}                 cause: "playedPastEnd" | "note" | "manual"
--   stopped                             dropout {seconds}
--   send {song, action, destination, reason}
--                                       reason: "entering" | "ending" | "manualFire" | "manualStop"
--   missingDestination {song, action}   armedChanged {armed}
--   sourceHealthChanged {role, healthy} liveSourceChanged {role}  role: "primary" | "backup"
--   alertChanged {alert}                alert: "primaryLostRunningOnBackup" | "allTimecodeLost" | nil

local timecode = require("timecode")

local engine = {}

-- How far, in frames, the Playhead may land from where natural playback
-- would have put it before the move counts as a Jump.
engine.JUMP_TOLERANCE_FRAMES = 5
-- A gap longer than this (but shorter than the Stop time) is a Dropout.
engine.DROPOUT_THRESHOLD = 0.2
-- A Timecode Source with no reading for longer than this is lost.
engine.SOURCE_LOSS_TIME = 0.25
engine.DEFAULT_STOP_TIME = 2
local STOP_TIME_MIN, STOP_TIME_MAX = 0.5, 30
local ROLES = { "primary", "backup" }

local Engine = {}
Engine.__index = Engine

local function append(list, more)
    for _, item in ipairs(more) do list[#list + 1] = item end
    return list
end

-- A Set ready for the engine: Songs keep their order, Destinations by id, the
-- Stop time within its range.
local function prepare(set)
    local destinations = {}
    for _, destination in ipairs(set.destinations or {}) do destinations[destination.id] = destination end
    local stopTime = set.stopTime or engine.DEFAULT_STOP_TIME
    return {
        songs = set.songs or {},
        destinations = destinations,
        stopTime = math.min(math.max(stopTime, STOP_TIME_MIN), STOP_TIME_MAX),
    }
end

-- `set` as described above; `armed` false unless given.
function engine.new(set, armed)
    return setmetatable({
        set = prepare(set or {}),
        isArmed = armed == true,
        isStopped = false,
        liveSource = "primary",
        playhead = nil, frameRate = nil, alert = nil,
        currentSong = nil, -- the Song most recently Entered, by timecode or note
        timecodeSong = nil, -- the Song whose span contains the Playhead
        stoppedAt = nil, -- where timecode was at a Stop, until the next reading
        lastReading = nil, -- the last reading followed, from the live source
        lastReadings = {}, -- the last reading from each source
        healthy = {},
        resumedAt = nil, -- when timecode last started arriving after silence or a Stop
    }, Engine)
end

function Engine:song(id)
    for _, song in ipairs(self.set.songs) do
        if song.id == id then return song end
    end
end

-- The Song whose span contains `position`; the first in list order if a
-- hand-made Set overlaps.
function Engine:songAt(position)
    for _, song in ipairs(self.set.songs) do
        if song.start and song.start <= position and position <= song["end"] then return song end
    end
end

function Engine:setArmed(armed)
    if armed == self.isArmed then return {} end
    self.isArmed = armed
    return { { kind = "armedChanged", armed = armed } }
end

-- Replaces the Set. Nothing fires here; the next reading applies it.
function Engine:updateSet(set)
    self.set = prepare(set)
end

-- The sends for one of a Song's Action lists, in list order. Automatic sends
-- are suppressed while disarmed.
function Engine:sends(songID, list, reason, evenIfDisarmed)
    local song = self:song(songID)
    if not (self.isArmed or evenIfDisarmed) or not song then return {} end
    local events = {}
    for _, action in ipairs(song[list] or {}) do
        local destination = self.set.destinations[action.destination]
        if destination then
            events[#events + 1] = { kind = "send", song = songID, action = action, destination = destination, reason = reason }
        else
            events[#events + 1] = { kind = "missingDestination", song = songID, action = action.id }
        end
    end
    return events
end

function Engine:enter(songID, cause)
    local events = {}
    if songID ~= self.currentSong then events[1] = { kind = "currentSongChanged", song = songID } end
    self.currentSong = songID
    events[#events + 1] = { kind = "fired", song = songID, cause = cause }
    return append(events, self:sends(songID, "startActions", "entering"))
end

function Engine:finish(songID, cause)
    return append({ { kind = "ended", song = songID, cause = cause } }, self:sends(songID, "stopActions", "ending"))
end

-- A Jump is any landing far from where natural playback from the previous
-- reading would be by now.
function Engine:isJump(previous, reading)
    local rate = reading.frameRate
    local elapsed = math.max(0, reading.timestamp - previous.timestamp)
    local expected = timecode.index(previous.timecode, rate) + elapsed * timecode.RATES[rate].real
    return math.abs(timecode.index(reading.timecode, rate) - expected) > engine.JUMP_TOLERANCE_FRAMES
end

function Engine:follow(reading)
    local events = {}
    if reading.frameRate ~= self.frameRate then
        self.frameRate = reading.frameRate
        events[#events + 1] = { kind = "frameRateChanged", frameRate = reading.frameRate }
    end

    local jumped = false
    local restarted = self.stoppedAt ~= nil
    -- Resuming after a Stop somewhere other than where it stopped is a
    -- relocation: like a Jump, it Ends nothing.
    local relocated = restarted and math.abs(timecode.index(self.stoppedAt, reading.frameRate)
        - timecode.index(reading.timecode, reading.frameRate)) > engine.JUMP_TOLERANCE_FRAMES
    self.stoppedAt = nil
    local previous = self.lastReading
    if previous then
        local gap = reading.timestamp - previous.timestamp
        if gap > engine.DROPOUT_THRESHOLD then events[#events + 1] = { kind = "dropout", seconds = gap } end
        if self:isJump(previous, reading) then
            jumped = true
            events[#events + 1] = { kind = "jumped", from = previous.timecode, to = reading.timecode }
        end
    end
    self.isStopped = false

    if reading.timecode ~= self.playhead then
        self.playhead = reading.timecode
        events[#events + 1] = { kind = "playheadMoved", timecode = reading.timecode }
    end
    self.lastReading = reading

    local song = self:songAt(reading.timecode)
    local songID = song and song.id
    if songID == self.timecodeSong and not (restarted and songID ~= nil) then return events end
    local left = self.timecodeSong
    self.timecodeSong = songID
    -- Only leaving the current Song matters; one a note displaced is gone already.
    local leftCurrent = left ~= nil and left == self.currentSong

    -- Playing on past its end time Ends a Song, before the next Song fires.
    -- A Jump out of a Song, or playing backwards out of it, does not.
    local leftSong = leftCurrent and self:song(left)
    if leftSong and not jumped and not relocated and reading.timecode > leftSong["end"] then
        append(events, self:finish(left, "playedPastEnd"))
    end

    -- Entering: arriving inside a Song from outside it, by playing or a Jump.
    if songID ~= nil then
        if songID == self.currentSong and not restarted then return events end
        append(events, self:enter(songID, "entering"))
    elseif leftCurrent then
        self.currentSong = nil
        events[#events + 1] = { kind = "currentSongChanged", song = nil }
    end
    return events
end

function Engine:isHealthy(role, time)
    local reading = self.lastReadings[role]
    return reading ~= nil and time - reading.timestamp <= engine.SOURCE_LOSS_TIME
end

function Engine:isLost(role, time)
    if not self.resumedAt or time - self.resumedAt <= engine.SOURCE_LOSS_TIME then return false end
    return not self:isHealthy(role, time)
end

-- Reports sources going healthy or lost, and the alert that follows.
function Engine:updateHealth(time)
    local events = {}
    for _, role in ipairs(ROLES) do
        local healthy = self:isHealthy(role, time)
        if healthy ~= (self.healthy[role] == true) then
            self.healthy[role] = healthy or nil
            events[#events + 1] = { kind = "sourceHealthChanged", role = role, healthy = healthy }
        end
    end
    local alert
    if not next(self.healthy) then
        -- Silence after a Stop, or before any timecode, is normal.
        alert = not (self.isStopped or self.resumedAt == nil) and "allTimecodeLost" or nil
    elseif self.liveSource == "backup" and not self.healthy.primary then
        alert = "primaryLostRunningOnBackup"
    end
    if alert ~= self.alert then
        self.alert = alert
        events[#events + 1] = { kind = "alertChanged", alert = alert }
    end
    return events
end

-- Feeds one reading { timecode, frameRate, timestamp } from the "primary"
-- (default) or "backup" source. Only the live source moves the Playhead; if
-- it is lost while this one is healthy, this one takes over seamlessly.
function Engine:handle(reading, role)
    role = role or "primary"
    local events = {}
    local previous = self.lastReadings[role]
    self.lastReadings[role] = reading
    if self.resumedAt == nil then self.resumedAt = reading.timestamp end
    if role ~= self.liveSource then
        if not self:isLost(self.liveSource, reading.timestamp) then
            return append(events, self:updateHealth(reading.timestamp))
        end
        self.liveSource = role
        events[#events + 1] = { kind = "liveSourceChanged", role = role }
        -- Follow on from this source's own last reading if it was running.
        if previous and reading.timestamp - previous.timestamp <= engine.SOURCE_LOSS_TIME then
            self.lastReading = previous
        end
    end
    append(events, self:follow(reading))
    return append(events, self:updateHealth(reading.timestamp))
end

-- A Note On (channel 0-15). Stop Notes first: a Song with only a Stop Note
-- sends its Stop Actions every time; otherwise it Ends the Song if current.
-- Then Start Notes Enter their Songs unless already current. Velocity 0 is a
-- Note Off and is ignored.
function Engine:handleNoteOn(channel, note, velocity)
    if (velocity or 0) <= 0 then return {} end
    local function matches(trigger) return trigger and trigger.channel == channel and trigger.note == note end
    local events = {}
    for _, song in ipairs(self.set.songs) do
        if matches(song.stopNote) then
            if not song.start and not song.startNote then
                append(events, self:finish(song.id, "note"))
            elseif song.id == self.currentSong then
                append(events, self:finish(song.id, "note"))
                self.currentSong = nil
                events[#events + 1] = { kind = "currentSongChanged", song = nil }
            end
        end
    end
    for _, song in ipairs(self.set.songs) do
        if matches(song.startNote) and song.id ~= self.currentSong then append(events, self:enter(song.id, "note")) end
    end
    return events
end

-- Lets time pass with no reading. Silence longer than the Set's Stop time is
-- a Stop: no Stop Actions, the current Song stays current but is re-armed.
function Engine:tick(time)
    local last = self.lastReading
    if self.isStopped or not last or time - last.timestamp <= self.set.stopTime then
        return self:updateHealth(time)
    end
    self.isStopped = true
    self.lastReading, self.resumedAt, self.stoppedAt = nil, nil, last.timecode
    local events = { { kind = "stopped" } }
    if self.liveSource ~= "primary" then
        self.liveSource = "primary"
        events[#events + 1] = { kind = "liveSourceChanged", role = "primary" }
    end
    return append(events, self:updateHealth(time))
end

-- Fires a Song's Start Actions by hand, even while disarmed. The current Song
-- is not changed.
function Engine:fire(songID)
    if not self:song(songID) then return {} end
    return append({ { kind = "fired", song = songID, cause = "manual" } },
        self:sends(songID, "startActions", "manualFire", true))
end

-- Sends a Song's Stop Actions by hand, even while disarmed.
function Engine:fireStop(songID)
    if not self:song(songID) then return {} end
    return append({ { kind = "ended", song = songID, cause = "manual" } },
        self:sends(songID, "stopActions", "manualStop", true))
end

return engine

end

modules["live"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- The Show Engine on the console: feeds it a timecode slot's time, turns the
-- Actions it sends into MA commands, and keeps the short log the panel shows.
-- Pure: the adapter reads the slot, runs the commands and passes the clock.

local engine = require("engine")
local timecode = require("timecode")
local plan = require("trigit_plan")
local commands = require("commands")

local live = {}
live.LOG_LENGTH = 8

local Live = {}
Live.__index = Live

-- `set` as engine.new takes it; `rate` one of timecode.RATES; `lineFor(destination)`
-- the In & Out OSC line number for a Set Destination, or nil if it has none.
function live.new(set, rate, lineFor, armed)
    local names = {}
    for _, song in ipairs(set.songs or {}) do names[song.id] = song.name end
    return setmetatable({
        engine = engine.new(set, armed), rate = rate, lineFor = lineFor, names = names,
        log = {}, outbox = {}, later = {},
    }, Live)
end

local function describe(action)
    local body = action[action.type] or {}
    if action.type == "osc" then return "OSC " .. tostring(body.address) end
    if action.type == "midiNote" then return ("note %s/%s"):format(tostring((body.channel or 0) + 1), tostring(body.note)) end
    if action.type == "msc" then return "MSC" end
    return "DMX pulse"
end

function Live:note(text, failed)
    table.insert(self.log, 1, { time = self.engine.playhead or "", text = text, failed = failed })
    self.log[live.LOG_LENGTH + 1] = nil
end

function Live:send(event, now)
    local song, destination = self.names[event.song] or "?", event.destination
    local command, release = plan.liveCommand(event.action, destination)
    if command and event.action.type == "osc" then
        local line = self.lineFor(destination)
        if line then
            command = command:gsub(commands.OSC_LINE:gsub("%p", "%%%0"), tostring(line))
        else
            command, release = nil, ('no OSC line for "%s": import the Set, or name a line "TrigIT %s"')
                :format(destination.name, destination.name)
        end
    end
    local what = ("%s: %s to %s"):format(song, describe(event.action), destination.name)
    if not command then return self:note(what .. " not sent: " .. release, true) end
    self.outbox[#self.outbox + 1] = command
    if type(release) == "table" then self.later[#self.later + 1] = { at = now + release.after, command = release.command } end
    self:note(what)
end

function Live:apply(events, now)
    for _, event in ipairs(events) do
        local kind, name = event.kind, self.names[event.song]
        if kind == "send" then
            self:send(event, now)
        elseif kind == "missingDestination" then
            self:note((name or "?") .. ": an Action's Destination isn't in the Set; not sent", true)
        elseif kind == "fired" then
            self:note(name .. (event.cause == "manual" and " fired by hand" or " entered")
                .. ((self.engine.isArmed or event.cause == "manual") and "" or " (disarmed: nothing sent)"))
        elseif kind == "ended" then
            self:note(name .. (event.cause == "manual" and " stopped by hand" or " ended"))
        elseif kind == "jumped" then
            self:note("Jump to " .. event.to)
        elseif kind == "stopped" then
            self:note("Timecode stopped")
        elseif kind == "dropout" then
            self:note(("Dropout of %.1f s"):format(event.seconds), true)
        end
    end
end

-- A reading of the slot: `seconds` of timecode at clock time `now`. Only a
-- new frame is a reading, so a slot that has stopped moving goes quiet and
-- tick() finds the Stop.
function Live:follow(seconds, now)
    local position = timecode.fromSeconds(seconds, self.rate)
    if position == self.position then return end
    self.position = position
    self:apply(self.engine:handle({ timecode = position, frameRate = self.rate, timestamp = now }), now)
end

function Live:tick(now)
    self:apply(self.engine:tick(now), now)
    for i = #self.later, 1, -1 do
        if self.later[i].at <= now then
            self.outbox[#self.outbox + 1] = table.remove(self.later, i).command
        end
    end
end

function Live:setArmed(armed) self:apply(self.engine:setArmed(armed), 0) end
function Live:fire(id, now) self:apply(self.engine:fire(id), now) end
function Live:fireStop(id, now) self:apply(self.engine:fireStop(id), now) end

-- The commands to run now, in order; each is returned once.
function Live:take()
    local out = self.outbox
    self.outbox = {}
    return out
end

return live

end

modules["artnet"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- Art-Net 4 ArtTimeCode packets, as Sources/TrigITProtocols/ArtNetTimecode.swift
-- writes them, for bridge mode: the TrigIT Mac app follows them as an Art-Net
-- Timecode Source.

local artnet = {}

artnet.PORT = 6454
local TYPE = { ["24"] = 0, ["25"] = 1, ["29.97 DF"] = 2, ["30"] = 3 }

-- The 19-byte packet for `position` ("hh:mm:ss:ff") at `rate`, on stream 0.
function artnet.timecode(position, rate)
    local h, m, s, f = position:match("^(%d+):(%d+):(%d+):(%d+)$")
    return "Art-Net\0" .. string.char(0x00, 0x97, 0x00, 14, 0x00, 0x00,
        tonumber(f), tonumber(s), tonumber(m), tonumber(h), TYPE[rate])
end

return artnet

end

modules["arguments"] = function()
-- SPDX-License-Identifier: GPL-3.0-or-later
-- The text after `Plugin <n>` (#98), as in `Plugin TrigIT "fire Intro"`.
-- parse(text) returns { verb = ..., song = ... }, or nil and what it accepts.
-- Pure Lua, no MA calls.

local M = {}

M.USAGE = 'TrigIT accepts: "open", "start", "arm", "disarm", "toggle", "fire <Song>", "stop", "quit"'

local PLAIN = { open = true, start = true, arm = true, disarm = true, toggle = true, stop = true, quit = true }

function M.parse(text)
    text = (text or ""):match("^%s*(.-)%s*$")
    if text == "" then return { verb = "open" } end
    local verb, rest = text:match("^(%S+)%s*(.*)$")
    verb = verb:lower()
    if verb == "fire" then
        local song = rest:match('^"(.*)"$') or rest
        if song == "" then return nil, 'fire needs a Song name, as in "fire Intro"' end
        return { verb = "fire", song = song }
    end
    if PLAIN[verb] and rest == "" then return { verb = verb } end
    return nil, ('"%s" is not a TrigIT command. %s'):format(text, M.USAGE)
end

return M

end

-- SPDX-License-Identifier: GPL-3.0-or-later
-- The grandMA3 side of the plugin, everything that touches MA. Running it
-- opens the TrigIT panel, which follows a timecode slot in one of two modes
-- (docs/adr/0003-ma3-plugin-modes.md):
--   Standalone  the Show Engine (live.lua) sends the Set's Actions while Armed.
--   Bridge      the slot goes to the TrigIT Mac app as Art-Net Timecode, and
--               the Mac app fires.
-- It can also import the Set as a Timecode Show that fires the Actions without
-- the plugin running. The rules are in src/.

local pluginName, componentName, signalTable, myHandle = ...

-- What an import writes, all marked with MARK in their Note so a re-import
-- finds and replaces them:
--   Sequence <n>  one cue per moment; each cue's Command sends that moment's
--                 Actions (SendOSC / SendMIDI).
--   Timecode <n>  one track playing that sequence, with a Goto event per cue
--                 at its time, following the chosen timecode slot.
--   OSC lines     "TrigIT <Destination>" in In & Out, made when asked.

local trigitPlan = require("trigit_plan")
local ma3 = require("ma3")
local live = require("live")
local timecode = require("timecode")
local artnet = require("artnet")
local arguments = require("arguments")

local MARK = "Made by the TrigIT plugin. Importing a Set again replaces it."
local RATES = { "24", "25", "29.97 DF", "30" }
local READOUT = { ["24"] = "24 fps", ["25"] = "25 fps", ["29.97 DF"] = "30 fps", ["30"] = "30 fps" }
local GOTO = 16 -- the Goto token of a timecode event

local function settle() coroutine.yield(0.05) end -- lets MA create child objects
local function plainName(text) return (text:gsub('"', "'")) end -- safe inside a command's quotes

local function plural(n, word) return ("%d %s%s"):format(n, word, n == 1 and "" or "s") end

local function say(title, text)
    MessageBox({ title = "TrigIT: " .. title, message = text, commands = { { value = 1, name = "OK" } } })
end

-- Ours if its Note starts with MARK. The Timecode's Note also keeps the frame rate.
local function owned(object)
    return object ~= nil and tostring(object:Get("Note") or ""):sub(1, #MARK) == MARK
end

-- MARK: Choosing the file

-- Set files (.trigit or .csv) in the library's trigit folder, the library
-- itself, and the top or trigit folder of each USB drive.
local function setFiles()
    local library = GetPath(Enums.PathType.Library)
    local folders = { { library .. "/trigit", "Library/trigit" }, { library, "Library" } }
    for _, drive in ipairs(Root().Temp.DriveCollect:Children()) do
        local kind = tostring(drive.DriveType)
        if kind ~= "Internal" and kind ~= "OldVersion" then
            folders[#folders + 1] = { drive.Path, drive.name }
            folders[#folders + 1] = { drive.Path .. "/trigit", drive.name .. "/trigit" }
        end
    end
    local files = {}
    for _, folder in ipairs(folders) do
        local ok, entries = pcall(DirList, folder[1], "*")
        for _, entry in ipairs(ok and entries or {}) do
            local name = entry.name or ""
            local lower = name:lower()
            if lower:match("%.trigit$") or lower:match("%.csv$") then
                files[#files + 1] = { label = name .. "  (" .. folder[2] .. ")", path = folder[1] .. "/" .. name, name = name }
            end
        end
    end
    return files, library .. "/trigit"
end

local function chooseFile()
    local files, folder = setFiles()
    if #files == 0 then
        say("no Set files", "No .trigit or .csv files were found.\n\nPut the Set in\n" .. folder
            .. "\nor on a USB stick (at the top or in a folder named trigit), then run the plugin again.")
        return nil
    end
    local labels = {}
    for i, file in ipairs(files) do labels[i] = file.label end
    local _, label = PopupInput({ title = "TrigIT Set", caller = GetFocusDisplay(), items = labels })
    for _, file in ipairs(files) do
        if file.label == label then return file end
    end
end

local function readFile(path)
    local file = io.open(path, "rb")
    if not file then return nil end
    local text = file:read("a")
    file:close()
    return text
end

-- MARK: Where things go

local function firstFree(pool, from)
    local n = from
    while pool[n] do n = n + 1 end
    return n
end

-- The Timecode and Sequence an earlier import made, if any.
local function previous()
    for _, tc in ipairs(DataPool().Timecodes:Children()) do
        if owned(tc) then
            local target = tc[1] and tc[1][2] and tc[1][2].Target
            return tc, (target and owned(target)) and target or nil
        end
    end
end

local function chooseOptions(setName, eventCount, follow)
    local tc, seq = previous()
    local defaults = {
        timecode = tc and tc.no or firstFree(DataPool().Timecodes, 1),
        sequence = seq and seq.no or firstFree(DataPool().Sequences, 101),
        slot = follow.slot,
        rate = follow.rate,
    }
    local slots = {}
    for n = 1, 16 do slots["Slot " .. n] = n end
    local rates = {}
    for i, rate in ipairs(RATES) do rates[rate] = i end
    local preset
    for i, rate in ipairs(RATES) do if rate == defaults.rate then preset = i end end

    while true do
        local reply = MessageBox({
            title = "TrigIT: import " .. setName,
            message = ("%s. Choose the frame rate of the show's timecode, "
                .. "the slot it arrives on, and where the Timecode Show and its Sequence go.%s"):format(
                plural(eventCount, "timecode event"), tc and ("\n\nTimecode %d%s from the last import will be replaced, if you keep the numbers.")
                    :format(tc.no, seq and (" and Sequence " .. seq.no) or "") or ""),
            commands = { { value = 1, name = "Next" }, { value = 0, name = "Cancel" } },
            inputs = {
                { name = "Timecode", value = tostring(defaults.timecode), whiteFilter = "0123456789", vkPlugin = "TextInputNumOnly" },
                { name = "Sequence", value = tostring(defaults.sequence), whiteFilter = "0123456789", vkPlugin = "TextInputNumOnly" },
            },
            selectors = {
                { name = "Frame rate", type = 1, values = rates, selectedValue = preset or 4 },
                { name = "Timecode slot", type = 0, values = slots, selectedValue = defaults.slot },
            },
        })
        if reply.result ~= 1 then return nil end
        local options = {
            timecode = tonumber(reply.inputs.Timecode), sequence = tonumber(reply.inputs.Sequence),
            rate = RATES[reply.selectors["Frame rate"]], slot = reply.selectors["Timecode slot"],
        }
        local problem
        local existingTC = options.timecode and DataPool().Timecodes[options.timecode]
        local existingSeq = options.sequence and DataPool().Sequences[options.sequence]
        if not options.timecode or options.timecode < 1 then
            problem = "Enter a Timecode number."
        elseif not options.sequence or options.sequence < 1 then
            problem = "Enter a Sequence number."
        elseif existingTC and not owned(existingTC) then
            problem = ('Timecode %d "%s" is already used, and not by TrigIT. Choose a free number.'):format(options.timecode, existingTC.name)
        elseif existingSeq and not owned(existingSeq) then
            problem = ('Sequence %d "%s" is already used, and not by TrigIT. Choose a free number.'):format(options.sequence, existingSeq.name)
        end
        if not problem then return options end
        say("choose again", problem) -- then ask again, with the free numbers suggested
    end
end

-- MARK: Destinations

local function oscLines() return Root().ShowData.OSCBase end

local function lineLabel(line)
    return ("%d: %s  (%s:%s)"):format(line.no, line.name, tostring(line.DestinationIP), tostring(line.Port))
end

-- Asks which In & Out OSC line each OSC Destination uses. Changes nothing
-- yet: returns { [name] = line number, or { ip, port } for a new line } and
-- notes for the summary, or nil if cancelled.
local function mapDestinations(plan)
    local usedOSC, usedMIDI = {}, {}
    for _, event in ipairs(plan.events) do
        if event.destination.osc_line_for then usedOSC[event.destination.osc_line_for] = true end
        if event.destination.midi_for then usedMIDI[event.destination.midi_for] = true end
    end
    local lines, notes = {}, {}
    for _, destination in ipairs(plan.destinations) do
        if usedOSC[destination.name] then
            local values, guess = { ["New OSC line"] = 0 }, 0
            for _, line in ipairs(oscLines():Children()) do
                values[lineLabel(line)] = line.no
                local sameAddress = tostring(line.DestinationIP) == (destination.host or "") and tonumber(line.Port) == destination.port
                if line.name == "TrigIT " .. destination.name or (sameAddress and guess == 0) then guess = line.no end
            end
            local address = destination.host and destination.host ~= ""
                and ("%s:%d"):format(destination.host, destination.port) or "no address in the Set"
            local reply = MessageBox({
                title = "TrigIT: OSC to " .. destination.name,
                message = ('Which In & Out OSC line sends to "%s" (%s)?\n\nA new line uses the IP address and port below.')
                    :format(destination.name, address),
                commands = { { value = 1, name = "Use" }, { value = 2, name = "Leave out" }, { value = 0, name = "Cancel" } },
                inputs = {
                    { name = "IP address", value = destination.host or "", whiteFilter = "0123456789." },
                    { name = "Port", value = tostring(destination.port or 8000), whiteFilter = "0123456789", vkPlugin = "TextInputNumOnly" },
                },
                selectors = { { name = "OSC line", type = 0, values = values, selectedValue = guess } },
            })
            if reply.result == 0 then return nil end
            if reply.result == 2 then
                notes[#notes + 1] = ('OSC to "%s" is left out.'):format(destination.name)
            else
                local number = reply.selectors["OSC line"]
                if number == 0 then
                    local ip, port = reply.inputs["IP address"], tonumber(reply.inputs.Port)
                    if not ip:match("^%d+%.%d+%.%d+%.%d+$") or not port or port < 1 or port > 65535 then
                        say("address needed", ('"%s" needs an IP address and a port 1-65535 for its new OSC line. Import again to retry.'):format(destination.name))
                        return nil
                    end
                    lines[destination.name] = { ip = ip, port = port }
                    notes[#notes + 1] = ('A new OSC line "TrigIT %s" will send to %s:%d.'):format(destination.name, ip, port)
                else
                    lines[destination.name] = number
                    if not oscLines()[number].SendCommand then
                        notes[#notes + 1] = ("Send Command will be switched on for OSC line %d: SendOSC needs it."):format(number)
                    end
                end
            end
        end
    end
    if next(lines) then
        if not oscLines().EnableOutput then notes[#notes + 1] = "OSC Enable Output will be switched on." end
        if tostring(oscLines().Interface) == "0.0" then
            notes[#notes + 1] = "OSC has no interface yet: choose one in Menu > In & Out > OSC > Interface, or nothing is sent."
        end
    end
    for _, destination in ipairs(plan.destinations) do
        if usedMIDI[destination.name] then
            notes[#notes + 1] = ('MIDI to "%s" goes out of this station\'s MIDI output.'):format(destination.name)
        end
    end
    return lines, notes
end

-- Makes the new OSC lines and switches on what SendOSC needs. Returns
-- { [name] = line number }.
local function setUpLines(choices)
    local numbers = {}
    for name, choice in pairs(choices) do
        local line
        if type(choice) == "table" then
            line = oscLines():Append()
            settle()
            line.Name = "TrigIT " .. name
            line.DestinationIP, line.Port, line.Mode = choice.ip, choice.port, false
            -- Send off, so MA's own playback feedback doesn't go to the device.
            line.Send = false
        else
            line = oscLines()[choice]
        end
        line.SendCommand = true
        numbers[name] = line.no
    end
    if next(numbers) then oscLines().EnableOutput = true end
    return numbers
end

-- MARK: Writing the show

local function write(options, cues, setName, progress)
    local name = plainName("TrigIT " .. setName)
    if DataPool().Timecodes[options.timecode] then Cmd(("Delete Timecode %d /NoConfirm"):format(options.timecode)) end
    if DataPool().Sequences[options.sequence] then Cmd(("Delete Sequence %d /NoConfirm"):format(options.sequence)) end
    settle()

    -- The sequence: Store makes it with Cue 1; the rest are appended.
    Cmd(('Store Sequence %d "%s"'):format(options.sequence, name))
    settle()
    local seq = DataPool().Sequences[options.sequence]
    seq:Set("Note", MARK)
    local cueHandles = {}
    for i, cue in ipairs(cues) do
        local handle
        if i == 1 then
            for _, child in ipairs(seq:Children()) do if child.no == 1000 then handle = child end end
        else
            handle = seq:Append()
            settle()
            handle:Set("No", tostring(i))
        end
        handle[1].Command = cue.command
        Cmd(('Label Sequence %d Cue %d "%s"'):format(options.sequence, i, plainName(cue.name)))
        cueHandles[i] = handle
        IncProgress(progress, 1)
    end

    -- The Timecode Show: one track playing the sequence, a Goto per cue.
    Cmd(('Store Timecode %d "%s"'):format(options.timecode, name))
    settle()
    local tc = DataPool().Timecodes[options.timecode]
    tc:Set("Note", MARK .. "\nFrame rate: " .. options.rate)
    tc.TCSlot = options.slot
    -- Follow the slot by itself: start when timecode arrives, stop when it stops.
    tc.AutoStart, tc.AutoStop = true, true
    tc.FrameReadout = READOUT[options.rate]
    local group = tc:Append()
    settle()
    local track = group[2]
    track.Target = seq
    settle()
    local events = track[1]:Append("CmdSubTrack")
    settle()
    for i, cue in ipairs(cues) do
        local event = events:Append()
        settle()
        event.Time = cue.seconds
        event.Token = GOTO
        event.CueDestination = cueHandles[i]
        IncProgress(progress, 1)
    end
    return tc, seq
end

-- MARK: Main

local function summary(plan, cues, options, notes, setName)
    local lines = {
        ("Timecode %d and Sequence %d will hold %s from %s, at %s fps on timecode slot %d.")
            :format(options.timecode, options.sequence, plural(#cues, "cue"), setName, options.rate, options.slot),
    }
    for _, note in ipairs(notes) do lines[#lines + 1] = note end
    if #plan.warnings > 0 then
        lines[#lines + 1] = "\n" .. plural(#plan.warnings, "warning") .. ":"
        for i, warning in ipairs(plan.warnings) do
            if i > 12 then
                lines[#lines + 1] = ("... and %d more, listed in the System Monitor."):format(#plan.warnings - 12)
                break
            end
            lines[#lines + 1] = warning
        end
    end
    return table.concat(lines, "\n")
end

-- Writes the Set in `file` ({ name, path }) as `text` into a Timecode Show.
local function import(file, text, follow)
    local setName = file.name:gsub("%.[^.]+$", "")

    -- The frame rate decides when Stop Actions fire, so plan once to count
    -- events, then again at the chosen rate.
    local isCSV = file.name:lower():match("%.csv$")
    local function makePlan(rate)
        if isCSV then return trigitPlan.fromCSV(text, { frameRate = rate }) end
        return trigitPlan.fromTrigit(text, { frameRate = rate })
    end
    local first, reason = makePlan("30")
    if not first then
        say("can't import", file.name .. "\n\n" .. reason)
        return
    end
    if #first.events == 0 then
        say("nothing to import", file.name .. " has no Actions the MA3 can send at a timecode."
            .. (#first.warnings > 0 and ("\n\n" .. table.concat(first.warnings, "\n")) or ""))
        return
    end

    local options = chooseOptions(setName, #first.events, follow)
    if not options then return end
    local plan = makePlan(options.rate)
    local choices, notes = mapDestinations(plan)
    if not choices then return end
    local placeholders = {}
    for name in pairs(choices) do placeholders[name] = 0 end
    local cues = ma3.cues(plan, placeholders)
    if #cues == 0 then
        say("nothing to import", "Every Action was left out, so there is nothing to write.")
        return
    end

    for _, warning in ipairs(plan.warnings) do Printf("TrigIT: " .. warning) end
    local reply = MessageBox({
        title = "TrigIT: ready to import " .. setName,
        message = summary(plan, cues, options, notes, setName),
        commands = { { value = 1, name = "Import" }, { value = 0, name = "Cancel" } },
    })
    if reply.result ~= 1 then return end

    local progress = StartProgress("TrigIT: importing " .. setName)
    SetProgressRange(progress, 0, 2 * #cues)
    local ok, problem = pcall(function()
        write(options, ma3.cues(plan, setUpLines(choices)), setName, progress)
    end)
    StopProgress(progress)
    if not ok then
        ErrPrintf("TrigIT: " .. tostring(problem))
        say("import failed", "Writing the Timecode Show failed:\n" .. tostring(problem)
            .. "\n\nUse Oops to undo anything half written.")
        return
    end
    say("imported", ("%s is in Timecode %d and Sequence %d.\n\nTimecode %d starts by itself when timecode arrives on "
        .. "slot %d, and each cue sends its Actions at its time."):format(setName, options.timecode, options.sequence,
        options.timecode, options.slot))
end

-- MARK: The panel

local SLOT_UNITS = 16777216 -- a timecode slot's Time counts 1/16777216 s
local PANEL = "TrigITPanel"
local RED = "Global.AlertText"

-- Kept in the show's global variables, so the panel opens as it was left.
local function setting(name) return (GetVar(GlobalVars(), "TrigIT" .. name)) end
local function remember(name, value) SetVar(GlobalVars(), "TrigIT" .. name, value) end

-- The In & Out OSC line for a Set Destination: the one named "TrigIT <name>"
-- (an import makes it), else the first that sends to its address.
local function lineFor(destination)
    local byAddress
    for _, line in ipairs(oscLines():Children()) do
        if line.name == "TrigIT " .. destination.name then return line.no end
        if not byAddress and tostring(line.DestinationIP) == destination.host and tonumber(line.Port) == destination.port then
            byAddress = line.no
        end
    end
    return byAddress
end

local state = { pending = nil, notice = "" }

local function follow()
    state.lastTime, state.lastMove = nil, nil
    state.show = state.set and live.new(state.set, state.rate, lineFor, false)
end

-- An earlier import's Timecode Show fires the same Actions on its own.
local function checkTwice()
    local tc = previous()
    state.twice = tc and tc.AutoStart and tonumber(tostring(tc.TCSlot)) == state.slot
        and ("Timecode %d also fires these Actions on slot %d: disarm here, or switch off its AutoStart"):format(tc.no, state.slot)
end

local function load(file, quietly)
    local text = readFile(file.path)
    if not text then
        if not quietly then say("can't read", "Could not read " .. file.path) end
        return
    end
    local set
    if file.name:lower():match("%.csv$") then
        state.notice = "A CSV Set can be imported to a Timecode Show. To follow it here, open it in TrigIT on the Mac and save it as a .trigit file."
    else
        local reason
        set, reason = trigitPlan.readSet(text)
        if not set then
            if not quietly then say("can't load", file.name .. "\n\n" .. reason) end
            return
        end
        state.notice = ""
    end
    state.file, state.text, state.set = file, text, set
    remember("SetPath", file.path)
    remember("SetName", file.name)
    follow()
end

local function songNamed(label)
    for _, song in ipairs(state.set and state.set.songs or {}) do
        if song.name == label then return song end
    end
end

local function chooseSong(title)
    local names = {}
    for _, song in ipairs(state.set and state.set.songs or {}) do names[#names + 1] = song.name end
    if #names == 0 then return nil end
    local _, label = PopupInput({ title = title, caller = GetFocusDisplay(), items = names })
    return songNamed(label)
end

-- What the buttons do, run from the panel's loop so dialogs can wait.
local actions = {}

function actions.load()
    local file = chooseFile()
    if file then load(file) end
end

function actions.settings()
    local slots, rates = {}, {}
    for n = 1, #Root().TimecodeSlots:Children() do slots["Slot " .. n] = n end
    for i, rate in ipairs(RATES) do rates[rate] = i end
    local preset = 4
    for i, rate in ipairs(RATES) do if rate == state.rate then preset = i end end
    local reply = MessageBox({
        title = "TrigIT: timecode",
        message = "The slot the show's timecode arrives on, and its frame rate. Changing them disarms the panel.",
        commands = { { value = 1, name = "OK" }, { value = 0, name = "Cancel" } },
        selectors = {
            { name = "Timecode slot", type = 0, values = slots, selectedValue = state.slot },
            { name = "Frame rate", type = 1, values = rates, selectedValue = preset },
        },
    })
    if reply.result ~= 1 then return end
    state.slot, state.rate = reply.selectors["Timecode slot"], RATES[reply.selectors["Frame rate"]]
    remember("Slot", state.slot)
    remember("Rate", state.rate)
    follow()
end

local function onMac()
    if state.mode ~= "Bridge" then return false end
    if state.show then state.show:note("In bridge mode the Mac app fires: use its Show screen", true) end
    return true
end

function actions.mode()
    local reply = MessageBox({
        title = "TrigIT: mode",
        message = "Standalone: this console sends the Set's Actions while Armed.\n"
            .. "Bridge: this console sends the timecode slot to the TrigIT Mac app as Art-Net Timecode, and the Mac app fires. "
            .. "Choose Art-Net Timecode as its Timecode Source.\n\n"
            .. "For bridge mode, enter the Mac's IP address, or a broadcast address such as 192.168.1.255.",
        commands = { { value = 1, name = "OK" }, { value = 0, name = "Cancel" } },
        inputs = { { name = "Mac IP address", value = state.bridgeTo or "", whiteFilter = "0123456789." } },
        selectors = { { name = "Mode", type = 1, values = { Standalone = 1, Bridge = 2 }, selectedValue = state.mode == "Bridge" and 2 or 1 } },
    })
    if reply.result ~= 1 then return end
    local mode, ip = reply.selectors.Mode == 2 and "Bridge" or "Standalone", reply.inputs["Mac IP address"]
    if mode == "Bridge" and not ip:match("^%d+%.%d+%.%d+%.%d+$") then
        say("address needed", "Bridge mode needs the Mac's IP address, such as 192.168.1.20.")
        return
    end
    state.mode, state.bridgeTo = mode, ip
    remember("Mode", mode)
    remember("BridgeTo", ip)
    if state.show then state.show:setArmed(false) end
end

-- Bridge mode: each new frame on the slot goes to the Mac once.
local function bridge(seconds)
    local position = timecode.fromSeconds(seconds, state.rate)
    if position == state.sent then return end
    state.sent = position
    if not state.udp then
        local ok, socket = pcall(_ENV.require, "socket")
        if not ok then
            state.bridgeProblem = "LuaSocket is not available on this station, so bridge mode can't send"
            return
        end
        state.udp = socket.udp()
        state.udp:setoption("broadcast", true)
    end
    local ok, problem = state.udp:sendto(artnet.timecode(position, state.rate), state.bridgeTo, artnet.PORT)
    state.bridgeProblem = not ok and ("Can't send to %s: %s"):format(state.bridgeTo, tostring(problem)) or nil
    if ok then state.frames = (state.frames or 0) + 1 end
end

function actions.fire()
    if onMac() then return end
    local song = chooseSong("Song to fire")
    if song and state.show then state.show:fire(song.id, Time()) end
end

function actions.stop()
    if onMac() then return end
    local current = state.show and state.show.engine.currentSong
    local song = current and { id = current } or chooseSong("Song to stop")
    if song and state.show then state.show:fireStop(song.id, Time()) end
end

function actions.quit()
    local reply = MessageBox({
        title = "TrigIT: quit",
        message = "Stop TrigIT? It disarms, stops following timecode and sends nothing until you run the plugin again.\n\n"
            .. "To keep TrigIT running, close the panel with its ✖ instead.",
        commands = { { value = 1, name = "Quit TrigIT" }, { value = 0, name = "Cancel" } },
    })
    if reply.result == 1 then state.quit = true end
end

function actions.import()
    if not state.file then actions.load() end
    if not state.file then return end
    import(state.file, state.text, { slot = state.slot, rate = state.rate })
end

local function text(parent, anchors, font, align)
    local object = parent:Append("UIObject")
    object.Anchors, object.Font, object.HasHover = anchors, font or "console18", "No"
    object.TextalignmentH, object.TextalignmentV = align or "Left", "Top"
    object.Text = ""
    return object
end

local function button(parent, anchors, label, action)
    local object = parent:Append("Button")
    object.Anchors, object.Text, object.Font = anchors, label, "Medium20"
    object.PluginComponent = myHandle
    object.Clicked = "TrigIT" .. action
    return object
end

local function rows(grid, sizes)
    grid.Columns, grid.Rows = 1, #sizes
    for i, size in ipairs(sizes) do
        if size == "*" then
            grid[1][i].SizePolicy = "Stretch"
        else
            grid[1][i].SizePolicy, grid[1][i].Size = "Fixed", tostring(size)
        end
    end
end

local function build(overlay)
    local ui = {}
    local base = overlay:Append("BaseInput")
    base.Name, base.W, base.H = PANEL, 1300, 720
    base.AutoClose, base.CloseOnEscape = "No", "Yes"
    rows(base, { 60, "*" })
    local title = base:Append("TitleBar")
    title.Columns, title.Rows, title.Anchors = 2, 1, "0,0"
    title[2][2].SizePolicy, title[2][2].Size = "Fixed", "60"
    local name = title:Append("TitleButton")
    name.Text, name.Anchors = "TrigIT", "0,0"
    title:Append("CloseButton").Anchors = "1,0"

    local frame = base:Append("DialogFrame")
    frame.Anchors = { left = 0, right = 0, top = 1, bottom = 1 }
    rows(frame, { 110, 50, "*", 80 })

    local top = frame:Append("UILayoutGrid")
    top.Anchors, top.Columns, top.Rows = "0,0", 3, 1
    ui.playhead = text(top, "0,0", "console32", "Center")
    ui.song = text(top, "1,0", "Regular32", "Center")
    ui.playhead.TextalignmentV, ui.song.TextalignmentV = "Center", "Center"
    ui.arm = button(top, "2,0", "", "Arm")
    ui.arm.Font = "Regular28"

    ui.status = text(frame, "0,1", "Regular20", "Center")
    ui.status.TextalignmentV = "Center"

    local lists = frame:Append("UILayoutGrid")
    lists.Anchors, lists.Columns, lists.Rows = "0,2", 2, 1
    lists[2][1].SizePolicy, lists[2][1].Size = "Fixed", "540"
    ui.songs = text(lists, "0,0")
    ui.log = text(lists, "1,0")

    local buttons = frame:Append("UILayoutGrid")
    buttons.Anchors, buttons.Columns, buttons.Rows = "0,3", 7, 1
    for i, entry in ipairs({ { "Load Set", "Load" }, { "Timecode", "Settings" }, { "Mode", "Mode" }, { "Fire Song", "Fire" },
        { "Stop Song", "Stop" }, { "Import Show", "Import" }, { "Quit", "Quit" } }) do
        button(buttons, (i - 1) .. ",0", entry[1], entry[2])
    end
    ui.base = base
    return ui
end

local function put(object, property, value)
    if object[property] ~= value then object[property] = value end
end

local ALERTS = {
    allTimecodeLost = "Timecode lost",
    primaryLostRunningOnBackup = "Primary timecode lost, running on backup",
}

local function render(ui, now)
    local show = state.show
    local engine = show and show.engine
    local current = engine and engine.currentSong
    local armed = engine and engine.isArmed

    put(ui.playhead, "Text", engine and engine.playhead or "--:--:--:--")
    local currentName
    for _, song in ipairs(state.set and state.set.songs or {}) do
        if song.id == current then currentName = song.name end
    end
    put(ui.song, "Text", currentName or "No Song")
    put(ui.arm, "Text", state.mode == "Bridge" and "BRIDGE" or armed and "ARMED" or "Disarmed")
    put(ui.arm, "BackColor", armed and RED or "Button.Background")

    local running = state.lastMove and now - state.lastMove < 0.5
    local first = state.mode == "Bridge" and ("Bridge to %s, %d frames sent"):format(state.bridgeTo, state.frames or 0)
        or state.file and state.file.name or "No Set loaded: Load Set"
    local status = ("%s   |   slot %d at %s fps, %s"):format(first, state.slot, state.rate,
        running and "timecode running" or "no timecode")
    local alert = engine and ALERTS[engine.alert or ""]
    local warning = alert or (state.mode == "Bridge" and state.bridgeProblem) or (armed and state.twice)
        or (state.notice ~= "" and state.notice)
    put(ui.status, "Text", warning or status)
    put(ui.status, "TextColor", warning and RED or "Global.Text")

    local songs = { " SONGS" }
    for _, song in ipairs(state.set and state.set.songs or {}) do
        local span = song.start and (song.start .. " - " .. song["end"]) or "notes only"
        songs[#songs + 1] = ("%s %s   %s"):format(song.id == current and ">" or " ", song.name, span)
    end
    put(ui.songs, "Text", table.concat(songs, "\n"))

    local log = { " LAST ACTIONS" }
    for _, entry in ipairs(show and show.log or {}) do
        log[#log + 1] = ("%s %-11s  %s"):format(entry.failed and "!" or " ", entry.time, entry.text)
    end
    put(ui.log, "Text", table.concat(log, "\n"))
end

-- The panel only shows TrigIT: closing it leaves the loop below running
-- (#94), and running the plugin again opens a new panel on the same state.
local function closePanel()
    local panel = GetDisplayByIndex(1).ScreenOverlay:FindRecursive(PANEL)
    if panel then panel:Parent():Remove(panel:Index()) end
end

local function openPanel()
    local overlay = GetDisplayByIndex(1).ScreenOverlay
    if not overlay:FindRecursive(PANEL) then state.ui = build(overlay) end
end

-- One TrigIT at a time: each start writes a new run token to the show's
-- global variables, and a loop whose token is gone ends. That covers a
-- re-imported plugin (a second copy of this file) and a newly loaded show.
local RUN = "Run"

-- Commands from a macro, an executor or the command line (#98), such as
-- Plugin TrigIT "arm". They act on the running TrigIT.
local function command(request)
    local verb = request.verb
    if verb == "open" then return openPanel() end
    if verb == "start" then return end -- running already: nothing to do
    if verb == "quit" then
        state.quit = true
        return Printf("TrigIT: stopping")
    end
    if verb == "stop" or verb == "fire" then
        if onMac() then return ErrPrintf("TrigIT: in bridge mode the Mac app fires") end
        if not state.show then return ErrPrintf("TrigIT: no Set loaded") end
        if verb == "stop" then
            local current = state.show.engine.currentSong
            if not current then return Printf("TrigIT: no current Song to stop") end
            return state.show:fireStop(current, Time())
        end
        for _, song in ipairs(state.set.songs) do
            if song.name:lower() == request.song:lower() then return state.show:fire(song.id, Time()) end
        end
        return ErrPrintf(('TrigIT: no Song named "%s" in %s'):format(request.song, state.file.name))
    end
    if state.mode == "Bridge" then return ErrPrintf("TrigIT: in bridge mode, arm on the Mac") end
    if not state.show then return ErrPrintf("TrigIT: no Set loaded, so nothing to arm") end
    local armed = state.show.engine.isArmed
    local want = verb == "arm" or (verb == "toggle" and not armed)
    if want ~= armed then state.show:setArmed(want) end
    Printf("TrigIT: " .. (want and "Armed" or "Disarmed"))
end

-- MA3 has no hook for a show load, and a show load ends every plugin (#99).
-- So the first start in a show makes a macro that starts TrigIT, for the
-- operator to run after loading the show or to put on a key.
local START_MACRO = "Made by the TrigIT plugin: run it after loading this show to start TrigIT, disarmed."

local function startMacro()
    if setting("StartMacro") then return end -- made once per show; deleting it turns this off
    local pool = DataPool().Macros
    for _, macro in ipairs(pool:Children()) do
        if tostring(macro:Get("Note") or "") == START_MACRO then return remember("StartMacro", tostring(macro.no)) end
    end
    local n = 1
    while pool[n] do n = n + 1 end
    Cmd(('Store Macro %d "TrigIT start"'):format(n))
    local macro = pool[n]
    if not macro then return ErrPrintf("TrigIT: could not make the TrigIT start macro") end
    macro:Append().Command = ('Plugin "%s" "start"'):format(plainName(myHandle:Parent().name))
    macro.Note = START_MACRO
    remember("StartMacro", tostring(n))
    Printf(("TrigIT: made Macro %d \"TrigIT start\". Run it after loading this show to start TrigIT."):format(n))
end

local function main(_, text)
    local request, why = arguments.parse(text)
    if not request then return ErrPrintf("TrigIT: " .. why) end
    local running = state.token and setting(RUN) == state.token
    if running then return command(request) end
    if request.verb == "quit" then return Printf("TrigIT is not running") end

    -- A stopped TrigIT's panel is reused; one left by another copy of the
    -- plugin (re-imported) is closed.
    if not (state.ui and IsObjectValid(state.ui.base)) then closePanel() end
    local tc = previous()
    state.slot = tonumber(setting("Slot")) or (tc and tonumber(tostring(tc.TCSlot))) or 1
    state.rate = setting("Rate") or (tc and tostring(tc:Get("Note")):match("Frame rate: (.+)$")) or "30"
    state.mode, state.bridgeTo = setting("Mode") or "Standalone", setting("BridgeTo")
    local path, name = setting("SetPath"), setting("SetName")
    if path and name then load({ path = path, name = name }, true) end

    local token = ("%.6f-%d"):format(Time(), math.random(1, 1e9))
    state.token, state.quit = token, false
    remember(RUN, token)
    for _, action in ipairs({ "Load", "Settings", "Mode", "Fire", "Stop", "Import", "Quit" }) do
        signalTable["TrigIT" .. action] = function() state.pending = action:lower() end
    end
    signalTable.TrigITArm = function()
        if state.show and state.mode ~= "Bridge" then state.show:setArmed(not state.show.engine.isArmed) end
    end
    local ok, problem = pcall(startMacro)
    if not ok then ErrPrintf("TrigIT: " .. tostring(problem)) end
    Printf("TrigIT is running. Closing its panel leaves it running; run the plugin again to reopen it, Quit to stop it.")
    command(request) -- opens the panel when asked to, or with no argument

    while state.token == token and not state.quit do
        local now = Time()
        local action = state.pending
        state.pending = nil
        if action then
            local ok, problem = pcall(actions[action])
            if not ok then ErrPrintf("TrigIT: " .. tostring(problem)) end
        end
        local show = state.show
        local slot = Root().TimecodeSlots[state.slot]
        local time = slot and slot.Time
        -- The slot's first value may be left from long ago: follow it once it moves.
        if time and time ~= state.lastTime then
            if state.lastTime then
                if show then show:follow(time / SLOT_UNITS, now) end
                if state.mode == "Bridge" then bridge(time / SLOT_UNITS) end
                state.lastMove = now
            end
            state.lastTime = time
        end
        if show then
            show:tick(now)
            for _, command in ipairs(show:take()) do
                local result = Cmd(command)
                if result ~= "OK" then show:note(("%s: %s"):format(command, tostring(result)), true) end
            end
        end
        -- An import, or someone at the console, may change an imported Timecode.
        if now - (state.checked or 0) > 1 then
            checkTwice()
            state.checked = now
            if setting(RUN) ~= token then state.token = nil end -- another TrigIT started, or another show was loaded
        end
        if state.ui and IsObjectValid(state.ui.base) then render(state.ui, now) end
        coroutine.yield(0)
    end

    if state.token and state.token ~= token then return end -- a newer run in this same state took over
    if state.show then state.show:setArmed(false) end
    state.token, state.show = nil, nil
    -- The panel stays: removing it from here right after its Quit dialog
    -- crashed onPC 2.5.1. It says TrigIT stopped and closes with its ✖.
    local ui = state.ui
    if ui and IsObjectValid(ui.base) then
        put(ui.playhead, "Text", "--:--:--:--")
        put(ui.song, "Text", "Stopped")
        put(ui.arm, "Text", "Stopped")
        put(ui.arm, "BackColor", "Button.Background")
        put(ui.status, "Text", "TrigIT stopped: nothing is sent. Close this panel, or run the plugin to start again.")
        put(ui.status, "TextColor", "Global.Text")
    end
    Printf("TrigIT stopped: nothing is sent until you run the plugin again.")
end

return main
